-- Run after supplier-rma-resolution.sql inside BEGIN ... ROLLBACK on TEST only.
SET LOCAL ROLE service_role;
DO $$
DECLARE r uuid; a uuid; b uuid; d uuid; ca uuid; cb uuid; cd uuid; ia uuid; ib uuid; ic uuid; v integer; fv integer; snapshot jsonb; finalized_version integer; blocked boolean; actor text:='resolution-fixture@example.invalid';
BEGIN
 INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,vat_scheme,supplier_invoice_nr) VALUES('TEST-RESOLUTION-'||gen_random_uuid(),current_date,'TEST RESOLUTION','margin','TEST ONLY') RETURNING id INTO r;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,sku,price_cents,compensation_cents,rma_registered) VALUES(r,0,'booked','TEST-BOOKED-SKU',10000,10000,true) RETURNING id INTO a;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,1,'RMA',20000) RETURNING id INTO b;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,2,'RMA',10000) RETURNING id INTO d;
 ca:=public.assign_reception_supplier_rma(r,array[a],NULL,true,false,actor);
 cb:=public.assign_reception_supplier_rma(r,array[b],NULL,false,false,actor);
 cd:=public.assign_reception_supplier_rma(r,array[d],NULL,false,false,actor);
 SELECT id INTO ia FROM public.supplier_rma_items WHERE case_id=ca;
 SELECT id INTO ib FROM public.supplier_rma_items WHERE case_id=cb;
 SELECT id INTO ic FROM public.supplier_rma_items WHERE case_id=cd;
 SELECT to_jsonb(i) INTO snapshot FROM public.refurb_reception_items i WHERE id=a;
 -- Pending decisions cannot be turned into receipts or finalized, even with a CN.
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=ca;
 blocked:=false;BEGIN PERFORM public.settle_supplier_rma('copy_item',jsonb_build_object('case_id',ca,'item_id',ia,'version',v),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_DECISION_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Pending decision copied to receipt';END IF;
 blocked:=false;BEGIN PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',ca,'version',v,'confirmed',true),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_DECISION_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Unknown supplier outcome finalized';END IF;
 -- A rejected booked item: zero award, preserved claim, no invented source status changes.
 PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',ca,'item_id',ia,'version',v,'decision','rejected','reason','TEST rejected before shipping'),actor);
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',ca,'item_id',ia,'version',v,'decision','approved'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_CONFLICT' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Stale decision accepted';END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=ca;
 blocked:=false;BEGIN PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',ca,'item_id',ia,'version',v,'expected_cents',12000,'received_cents',0),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_CLAIM_LOCKED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Original claim overwritten';END IF;
 blocked:=false;BEGIN PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',ca,'item_id',ia,'version',v,'expected_cents',10000,'received_cents',1),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_RECEIPT_EXCEEDS_AWARD' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Rejected claim recorded as received';END IF;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',ca,'version',v,'stage','rejected','supplier_reference','TEST-REJECTION-REF'),actor);
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=ca;
 PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',ca,'version',v,'confirmed',true),actor);
 SELECT version INTO finalized_version FROM public.supplier_rma_cases WHERE id=ca;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_cases WHERE id=ca AND stage='handled' AND supplier_credit_note='') THEN RAISE EXCEPTION 'Rejected zero-award requires fake CN';END IF;
 -- Repair remains available after the financial dossier is final, but not without custody.
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',ca,'item_id',ia,'followup_version',0,'repair_state','queued'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_RETURN_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Repair started without physical confirmation';END IF;
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',ca,'item_id',ia,'followup_version',0,'custody','on_site'),actor);
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ia;
 PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',ca,'item_id',ia,'followup_version',fv,'repair_state','queued'),actor);
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ia;
 PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',ca,'item_id',ia,'followup_version',fv,'repair_state','working','repair_notes','TEST work','repair_parts','-'),actor);
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ia;
 PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',ca,'item_id',ia,'followup_version',fv,'repair_state','quality','repair_notes','TEST repaired','repair_parts','-'),actor);
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ia;
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',ca,'item_id',ia,'followup_version',fv,'repair_state','repaired','repair_notes','TEST repaired','repair_parts','-'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_QUALITY_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Unconfirmed quality approved';END IF;
 PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',ca,'item_id',ia,'followup_version',fv,'repair_state','repaired','repair_notes','TEST repaired and tested','repair_parts','-','quality_confirmed',true),actor);
 IF (SELECT to_jsonb(i) FROM public.refurb_reception_items i WHERE id=a) IS DISTINCT FROM snapshot THEN RAISE EXCEPTION 'Booked source changed';END IF;
 IF (SELECT version FROM public.supplier_rma_cases WHERE id=ca)<>finalized_version THEN RAISE EXCEPTION 'Final financial case changed by repair';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_followups WHERE case_item_id=ia AND repair_state='repaired' AND completed_at IS NOT NULL) THEN RAISE EXCEPTION 'Repair completion missing';END IF;
 -- Declined after dispatch: a real return is mandatory; other-case IDs and stale updates fail.
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cb;
 PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',cb,'item_id',ib,'version',v,'decision','rejected','reason','TEST rejected after shipping'),actor);
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',cb,'item_id',ib,'followup_version',0,'custody','returning','outbound_on',current_date-2),actor);
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ib;
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',cb,'item_id',ib,'followup_version',fv,'repair_state','queued'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_RETURN_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Repair allowed while return pending';END IF;
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',cb,'item_id',ib,'followup_version',fv,'custody','on_site'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_RETURN_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Dispatched history erased';END IF;
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',cb,'item_id',ib,'followup_version',fv,'custody','returned','outbound_on',current_date-2,'returned_on',current_date),actor);
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',cb,'item_id',ib,'followup_version',fv,'repair_state','queued'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_CONFLICT' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Stale follow-up accepted';END IF;
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ib;
 PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',cb,'item_id',ib,'followup_version',fv,'repair_state','queued'),actor);
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',ca,'item_id',ib,'followup_version',0,'custody','on_site'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_ITEM_NOT_FOUND' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Cross-case operation accepted';END IF;
 -- Partial award: copy the award, not the claim. CN and an explicit write-off are required.
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',cd,'item_id',ic,'version',v,'decision','partial','approved_cents',4000),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_REASON_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Partial award lacks reason';END IF;
 PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',cd,'item_id',ic,'version',v,'decision','partial','approved_cents',4000,'reason','TEST partial credit'),actor);
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 PERFORM public.settle_supplier_rma('copy_item',jsonb_build_object('case_id',cd,'item_id',ic,'version',v),actor);
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE id=ic AND expected_cents=10000 AND approved_cents=4000 AND received_cents=4000) THEN RAISE EXCEPTION 'Arrow used original claim';END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',cd,'item_id',ic,'version',v,'expected_cents',10000,'received_cents',1500),actor);
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',cd,'version',v,'stage','closed','supplier_reference','TEST-PARTIAL-REF'),actor);
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 blocked:=false;BEGIN PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',cd,'version',v,'confirmed',true,'confirm_writeoff',true),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_FINAL_FIELDS_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Positive award finalized without CN';END IF;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',cd,'version',v,'stage','closed','supplier_reference','TEST-PARTIAL-REF','supplier_credit_note','TEST-CN'),actor);
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 blocked:=false;BEGIN PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',cd,'version',v,'confirmed',true),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_WRITEOFF_CONFIRMATION' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Unconfirmed debt write-off';END IF;
 PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',cd,'version',v,'confirmed',true,'confirm_writeoff',true),actor);
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE id=ic AND expected_cents=10000 AND approved_cents=4000 AND received_cents=1500 AND written_off_cents=2500) THEN RAISE EXCEPTION 'Final financial split incorrect';END IF;
 UPDATE public.refurb_reception_items SET refurb_status='Refunded' WHERE id=d;
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',cd,'item_id',ic,'followup_version',0,'custody','on_site'),actor);
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ic;
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',cd,'item_id',ic,'followup_version',fv,'repair_state','queued'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_REFUNDED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Refunded device restarted as internal RMA';END IF;
 IF has_function_privilege('anon','public.resolve_supplier_rma(text,jsonb,text)','EXECUTE') OR has_function_privilege('authenticated','public.resolve_supplier_rma(text,jsonb,text)','EXECUTE') THEN RAISE EXCEPTION 'Public resolution RPC';END IF;
 IF has_table_privilege('anon','public.supplier_rma_followups','SELECT') OR NOT (SELECT relrowsecurity FROM pg_class WHERE oid='public.supplier_rma_followups'::regclass) THEN RAISE EXCEPTION 'Follow-up data exposed';END IF;
END $$;
SELECT 'supplier_rma_resolution: before/after shipping, booked preservation, final repair continuation, partial finances, concurrency and ACL verified' AS result;
